import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Favorites","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Adding Favorite Items","slug":"_1-adding-favorite-items","link":"#_1-adding-favorite-items","children":[]},{"level":2,"title":"2. Managing List & Drag-and-Drop Ordering","slug":"_2-managing-list-drag-and-drop-ordering","link":"#_2-managing-list-drag-and-drop-ordering","children":[]},{"level":2,"title":"3. Search Recall & Visual Appearance","slug":"_3-search-recall-visual-appearance","link":"#_3-search-recall-visual-appearance","children":[]}],"relativePath":"user-guide/settings/favorites.md","filePath":"user-guide/settings/favorites.md","lastUpdated":1791112464000}`),a={name:`user-guide/settings/favorites.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="favorites" tabindex="-1">Favorites <a class="header-anchor" href="#favorites" aria-label="Permalink to “Favorites”">​</a></h1><p>Favorites allows you to pin frequently accessed folders, files, scripts, or web URLs with custom display names and top search priority. The settings page is located at <strong>Settings → Favorites</strong>.</p><h2 id="_1-adding-favorite-items" tabindex="-1">1. Adding Favorite Items <a class="header-anchor" href="#_1-adding-favorite-items" aria-label="Permalink to “1. Adding Favorite Items”">​</a></h2><p>Using the form at the top:</p><ul><li><strong>Display Name</strong>: Optional custom alias. If left empty and the target is a local path, Lertaro automatically uses the target folder or filename.</li><li><strong>Target Path</strong>: Accepts absolute local file/directory paths, environment variables such as <code>%USERPROFILE%</code>, Windows Shell virtual paths such as <code>shell:Downloads</code>, or full URLs starting with <code>http://</code> / <code>https://</code>.</li><li><strong>Browse Picker</strong>: Click <strong>Browse Folder</strong> or <strong>Browse File</strong> to open native selection dialogs.</li><li><strong>Add</strong>: Click <strong>Add</strong> once a valid path is entered to save the item.</li></ul><h2 id="_2-managing-list-drag-and-drop-ordering" tabindex="-1">2. Managing List &amp; Drag-and-Drop Ordering <a class="header-anchor" href="#_2-managing-list-drag-and-drop-ordering" aria-label="Permalink to “2. Managing List &amp; Drag-and-Drop Ordering”">​</a></h2><p>The list below displays all saved favorites with granular management controls:</p><ul><li><strong>Six-Dot Drag Handle</strong>: Every row includes a six-dot drag handle on the left to reorder items via drag-and-drop. You can also use the <strong>Move Up</strong> / <strong>Move Down</strong> buttons. The sequence here directly determines their ranking in search results and Quick Navigation menus.</li><li><strong>Edit Item</strong>: Turns the selected row into an inline editor. Save or cancel directly in that row; the top add form is not reused.</li><li><strong>Delete Item</strong>: Safely removes the entry from Favorites.</li><li><strong>Clear list</strong>: When the list is non-empty, the button beside the list heading removes all favorites at once; it is hidden when the list is empty.</li></ul><p>You can also add a single existing file or folder directly from the search result action menu. Lertaro asks for the display name, and hides this action when the same path is already in Favorites.</p><h2 id="_3-search-recall-visual-appearance" tabindex="-1">3. Search Recall &amp; Visual Appearance <a class="header-anchor" href="#_3-search-recall-visual-appearance" aria-label="Permalink to “3. Search Recall &amp; Visual Appearance”">​</a></h2><ul><li><strong>Starred Star Badge (★)</strong>: Matching favorite items display a prominent <strong>★</strong> badge beside their path in search results.</li><li><strong>Custom Alias Recall</strong>: Assign memorable names to deeply nested paths (e.g. naming <code>D:\\Workspace\\2026\\Q1\\Financial\\Summary.xlsx</code> as <code>Q1 Financials</code>). Searching for the alias recalls the item.</li><li><strong>Multi-surface Aggregation</strong>: Favorites automatically sync to the <a href="./../hotkeys.html#_3-quick-navigation-mouse-triggers"><strong>Quick Navigation</strong></a> menu and the <a href="./quick-panel.html#_4-plugin-tabs"><strong>Quick Panel</strong></a> Favorites tab.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};